// Trois versions : v1 {name, city}  →  v2 {first_name, last_name, city}  →  v3 {first_name, last_name, address:{city}}.
func upgraders() []Upgrader {
	return []Upgrader{
		func(d Doc) (Doc, error) {
			name, ok := d["name"].(string)
			if !ok {
				return nil, errors.New("name manquant")
