	c := newColl()
	c.PutRaw("b", Doc{"name": "Alan Turing", "city": "Wilmslow"})
	c.PutRaw("a", Doc{"name": "Ada Lovelace", "city": "Londres"})
	c.Put("c", Doc{"first_name": "Grace"})
	if p := c.PendingMigration(); p != 2 {
		t.Fatalf("PendingMigration = %d, attendu 2", p)
	}
