	if err != nil || n != 2 {
		t.Fatalf("Migrate = %d, %v, attendu 2, nil", n, err)
	}
	raw, _ := c.Raw("a")
	want := Doc{"_v": 3, "first_name": "Ada", "last_name": "Lovelace", "address": map[string]any{"city": "Londres"}}
	if !reflect.DeepEqual(raw, want) {
