	if err := Withdraw(&a, 1); !errors.Is(err, ErrInsufficient) || a.Balance != 0 {
		t.Errorf("solde insuffisant : %v, solde %d", err, a.Balance)
	}
	if err := Withdraw(&a, 0); !errors.Is(err, ErrAmount) {
		t.Errorf("montant nul : %v", err)
