			t.Errorf("ParseOptionalInt(%q) = (%v, %v), attendu (nil, erreur)", in, got, err)
		}
	}
	a, _ := ParseOptionalInt("5")
	b, _ := ParseOptionalInt("5")
	if a == b {
		t.Errorf("chaque appel doit renvoyer un pointeur distinct")
